window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"wFZtvxcWaOA","speaker":"Yamandú Orsi","role":"President","country":"Uruguay","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=wFZtvxcWaOA","date":"20260924","title":"🇺🇾 Uruguay - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":929,"words":1888,"counts":{"claims":18,"promises":3,"attacks":1},"topics":[{"topic":"US history","share":0.0832,"seconds":77},{"topic":"Border security","share":0.0817,"seconds":76},{"topic":"Human rights","share":0.077,"seconds":71},{"topic":"Cuba","share":0.075,"seconds":70},{"topic":"UN reform","share":0.0741,"seconds":69},{"topic":"Uruguay domestic stability","share":0.0697,"seconds":65},{"topic":"Diplomacy","share":0.0693,"seconds":64},{"topic":"Future of humanity","share":0.0682,"seconds":63},{"topic":"Conflict resolution","share":0.0681,"seconds":63},{"topic":"Global peace","share":0.0677,"seconds":63},{"topic":"Development aid","share":0.0674,"seconds":63},{"topic":"UN operations","share":0.067,"seconds":62},{"topic":"Uruguay military","share":0.0663,"seconds":62},{"topic":"Global inequality","share":0.0654,"seconds":61}],"timeline":[[4,82,"US history"],[84,149,"Uruguay domestic stability"],[150,211,"Uruguay military"],[213,276,"Conflict resolution"],[278,348,"Cuba"],[349,413,"Diplomacy"],[415,475,"Global inequality"],[476,539,"Development aid"],[540,611,"Human rights"],[612,676,"Future of humanity"],[677,740,"Global peace"],[741,810,"UN reform"],[811,887,"Border security"],[891,953,"UN operations"],[960,965,null]],"stances":{"US history":"Yamandú Orsi pays tribute to the people of the United States for their historical decision regarding fundamental rights and governance.","Uruguay domestic stability":"Yamandú Orsi defines Uruguay's national vocation as building a society based on dignity, freedom, and peaceful coexistence rather than merely administering resources.","Uruguay military":"Yamandú Orsi reaffirms Uruguay's commitment to contributing to peacekeeping missions and highlights the country's history of resolving differences through dialogue.","Conflict resolution":"Yamandú Orsi asserts that peacebuilding is an ongoing responsibility for every generation and that all human suffering demands a collective response regardless of geography.","Cuba":"Yamandú Orsi states that Uruguay does not believe taking sides in conflicts contributes to resolution and instead seeks dialogue, while specifically citing the suffering caused by the economic blockade on Cuba.","Diplomacy":"Yamandú Orsi argues that international relations should be based on humility, rejecting the idea that any single nation holds absolute truth or a monopoly on solutions.","Global inequality":"Yamandú Orsi states that extreme inequality, poverty, and war are major threats to coexistence while basic human needs remain unmet.","Development aid":"Yamandú Orsi argues that development, economies, technology, and politics must serve to improve people's lives, expand freedoms, and bring happiness.","Human rights":"Yamandú Orsi argues that human freedom is the fundamental driver of progress and change, rooted in the ability to recognize suffering and refuse inertia.","Future of humanity":"Yamandú Orsi argues that expanding freedom through dialogue and building enduring institutions allows humanity to progress toward a better world for future generations.","Global peace":"Yamandú Orsi argues that inequality, war, and poverty are not inevitable and that peace is an achievable ongoing endeavor based on human interconnectedness.","UN reform":"Yamandú Orsi argues that the UN must evolve to reflect current geopolitical changes and ensure all nations play an active role.","Border security":"Yamandú Orsi argues that national borders must be protected to preserve identity and stability, rejecting external economic pressures or the influence of a few countries.","UN operations":"Yamandú Orsi argues that the UN should be used to build and choose peace rather than to accuse or attack other nations."},"claims":[{"t":58,"quote":"people of the United States who 250 years ago, a quarter of a millennium ago, decided and understood that people have rights","topic":"US history","kind":"fact"},{"t":93,"quote":"inherited these same principles 50 years on","topic":"Uruguay domestic stability","kind":"fact"},{"t":106,"quote":"A country that, over the course of its history, has learned that governing doesn't merely mean administering resources or institutions","topic":"Uruguay domestic stability","kind":"fact"},{"t":184,"quote":"In this assembly, we reaffirm our enduring willingness to contribute to peacekeeping missions with a deep sense of responsibility","topic":"Uruguay military","kind":"fact"},{"t":213,"quote":"We are not a country given to grand gestures. We are a country of deeply held beliefs.","topic":"Conflict resolution","kind":"fact"},{"t":250,"quote":"When people suffer, humanity as a whole bears a responsibility.","topic":"Conflict resolution","kind":"fact"},{"t":296,"quote":"the suffering triggered by a rigid economic blockade such as that endured by the Cuban people.","topic":"Cuba","kind":"fact"},{"t":373,"quote":"No one is better than anyone else. No country holds the absolute truth. No nation has a monopoly on their solutions.","topic":"Diplomacy","kind":"fact"},{"t":382,"quote":"No society can claim that its historical experience is universal. And no people be doomed to choose between models imposed from outside.","topic":"Diplomacy","kind":"fact"},{"t":440,"quote":"Extreme inequality remains one of the great threats to coexistence. Poverty continues to deprive millions of people of basic opportunities, and wars continue to destroy lives, communities, and hopes.","topic":"Global inequality","kind":"fact"},{"t":487,"quote":"Development makes sense when it improves people's lives. Economies make sense when they serve Technology makes sense when it expands our freedoms and opportunities. And politics makes sense when it is able to transform reality to bring happiness to our people.","topic":"Development aid","kind":"fact"},{"t":649,"quote":"there are more than 8 billion people living on the same planet. 8 billion different stories, 8 billion hopes, 8 billion possibilities.","topic":"Future of humanity","kind":"number"},{"t":687,"quote":"We could accept mistrust replacing Or, on the contrary, we could choose another path.","topic":"Global peace","kind":"fact"},{"t":718,"quote":"No conflict is ever definitively resolved through more conflict.","topic":"Global peace","kind":"fact"},{"t":722,"quote":"No society becomes safer when hopelessness becomes the norm.","topic":"Global peace","kind":"fact"},{"t":778,"quote":"Every day the UN has an increasing reason to exist, and it must inevitably evolve in step with the geopolitical changes unfolding at dizzying speed.","topic":"UN reform","kind":"fact"},{"t":811,"quote":"Countries borders cannot be subject to human whims. They must be protected and as they represent the boundaries established to preserve identity, distinctive character, and a sense of belonging of their respective populations.","topic":"Border security","kind":"fact"},{"t":828,"quote":"We cannot continue to be held hostage to the will of a handful of countries that can be counted on the fingers of one hand.","topic":"Border security","kind":"fact"}],"promises":[{"t":209,"quote":"You can continue to count on Uruguay here","topic":"Uruguay military","kind":"promise"},{"t":861,"quote":"And we have made a commitment. Let us honor it right now.","topic":"Border security","kind":"promise"},{"t":872,"quote":"Uruguay will continue to support dialogue, multilateralism, cooperation, international law, and the peaceful settlement of disputes, and above all, for the dignity of every human being.","topic":"Border security","kind":"promise"}],"attacks":[{"t":925,"quote":"merely using this rostrum to accuse or attack fire. The fire doesn't need any more","topic":"UN operations","target":"UN member states"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":4,"topic":"US history","text":"The assembly will hear an address by His Excellency Yamandu Orsi, President of the Oriental Republic of Uruguay. I request protocol to escort His Excellency and invite him to address the &gt;&gt; Señor Presidente &gt;&gt; Mr. President of the General Assembly, Mr. Secretary General, heads of state, ladies and gentlemen, it is fitting that I begin by paying tribute to the people of the United States who 250 years ago, a quarter of a millennium ago, decided and understood that people have rights, the right to life, to their liberty and to happiness, and that these rights should guide every government, and that it is the governed who should decide who should govern them."},{"t":84,"topic":"Uruguay domestic stability","text":"in South America, also peoples of migrants, inherited these same principles 50 years on, and to that we say cheers. I appear before this assembly on behalf of a young country, but one with deeply rooted traditions. A country that, over the course of its history, has learned that governing doesn't merely mean administering resources or institutions. Above all, it means working for the well-being of And that has been one of Uruguay's great purposes, building a society in which dignity, freedom, peaceful coexistence, and opportunities can be a part of people's everyday lives. And if there is one word that sums up much of our vocation as a country, that word would be peace. We do not view peace simply as an absence of war."},{"t":150,"topic":"Uruguay military","text":"We understand it as something that has to be constantly built. The possibility for people to live, to work, to educate their children, pursue their aspirations, and to look to the future without fear. with its virtues, but also like every country with its darker times, has been a country that has sought to resolve its differences through institutions, through dialogue, and through the quest for agreement. In this assembly, we reaffirm our enduring willingness to contribute to peacekeeping missions with a deep sense of responsibility and Uruguayan men and women can bear witness to the value of this instrument in easing suffering and guaranteeing respect for the human lives of the most defenseless populations. You can continue to count on Uruguay here."},{"t":213,"topic":"Conflict resolution","text":"We are not a country given to grand gestures. We are a country of deeply held beliefs. And one of these beliefs is that peacebuilding is never finished. We can't take it for granted. Every generation has the responsibility to build it anew. There can't be peace for some and another peace for others. No suffering matters more because it happens closer to home and no lives are worth less because they were born in another country. When people suffer, humanity as a whole bears a responsibility. When a people is displaced, when a family loses its home, when young people can see no way out and their mental health is under threat, when a child grows up under the sound of gunfire, when millions of people live in poverty or without any opportunities, we can't stand indifferent to that."},{"t":278,"topic":"Cuba","text":"Nor can we stand indifferent to the pain caused by a state of endless war, the fear and pain generated by organized crime or the constant threat of the repression born out of tyranny, or the suffering triggered by a rigid economic blockade such as that endured by the Cuban people. We don't believe that taking one side or another in a war, confrontation, or dispute necessarily contributes to resolving it. Indeed, very often it only serves to further the divisions. We have a different commitment, that is to seek paths towards understanding, to open spaces for dialogue, and to help to ensure that conflicts find a peaceful This doesn't mean indifference. It doesn't mean downplaying suffering. It doesn't mean overlooking It means understanding that peace demands something more difficult than merely taking sides."},{"t":349,"topic":"Diplomacy","text":"It means that we need to work so that that confrontation can be brought to an end as soon as possible. And to do that, we also have to recover something that at times seems to have been lost in international debate, Uruguayans have an expression that sums up an understanding of coexistence. No one is better than anyone else. No country holds the absolute truth. No nation has a monopoly on their solutions. No society can claim that its historical experience is universal. And no people be doomed to choose between models imposed from outside. Our understanding of relations among countries stems from that notion of humil- humility. This is a humility that doesn't mean weakness. On the contrary, it means recognizing our own limitations, while at the same time trusting in the abilities of others."},{"t":415,"topic":"Global inequality","text":"We come from a country that is diverse in its opinions, but one that is deeply committed to the possibility of building a common future. And we believe that this combination, diversity of ideas and cohesion around the future, can also serve as our contribution to the international Today, we are living through a particularly difficult period. Extreme inequality remains one of the great threats to coexistence. Poverty continues to deprive millions of people of basic opportunities, and wars continue to destroy lives, communities, and hopes. While we discuss growth, technology, artificial intelligence, the energy transition, or new forms of production. There are millions of people who continue to ask themselves far more basic questions. How will I feed my children?"},{"t":476,"topic":"Development aid","text":"How can I find housing? How can I find a job? Or how can I face tomorrow without fear? We mustn't lose sight of that reality. Development makes sense when it improves people's lives. Economies make sense when they serve Technology makes sense when it expands our freedoms and opportunities. And politics makes sense when it is able to transform reality to bring happiness to our people. We are speaking from the experience of a small country removed from the great centers of power. However, we're convinced that our size shouldn't determine our ability to contribute, much less affect our own dignity. We need more effective, more representative multilateral institutions that are closer to the people and more able to respond to the challenges of our We need cooperation."},{"t":540,"topic":"Human rights","text":"We need solidarity. And we also need to demonstrate austerity within these institutions. But above all, we need to restore trust in our collective ability to change things at its heart, the very idea of well-being and progress springs from something that is profoundly human, that is the ability to recognize suffering and refuse to accept inertia. Human beings are creative precisely because they refuse to resign themselves to things. They sense what causes pain. They sense what could be different, and then they're able to sense the desire for change. And this desire for change is perhaps one of the most profound expressions of our own freedom. When our peoples advance along the path of progress, they generally do so by wielding the powerful magic of freedom. Knowing that freedom doesn't come involve solely choosing between different possibilities, it also means having being able to transform those things that we wish to for the good of the community as a whole."},{"t":612,"topic":"Future of humanity","text":"Our freedom becomes fuller when we are able to expand the freedom of others, when we change our societies through dialogue. When we build more we build fairer institutions, when we undertake significant projects that endure beyond our own lifetimes. When school a new school opens its doors, when a child has an opportunity that was previously out of their reach, when a community is able to overcome a division, when two countries that were at odds finally find a path towards understanding. there are more than 8 billion people living on the same planet. 8 billion different stories, 8 billion hopes, 8 billion possibilities. We're not finished as such as humanity. We are a humanity still in the making. Every morning we have the chance to decide what kind of world we want to leave to those who come after us."},{"t":677,"topic":"Global peace","text":"We can choose to accept inequality as inevitable. We could accept war as something permanent. Accept poverty as our fate. We could accept mistrust replacing Or, on the contrary, we could choose another path. most difficult path, but also the most human one. Uruguay therefore comes before this assembly today with that belief, with the humility and respect of a small country, but also with the resolve of those who understand the value of their principles. We've come to say that peace is no utopia. It is an ongoing endeavor. No conflict is ever definitively resolved through more conflict. No society becomes safer when hopelessness becomes the norm. No country can build its well-being in isolation. The future of humanity will, to a large extent, depend on our ability to understand that we are profoundly interconnected."},{"t":741,"topic":"UN reform","text":"We are different. We think differently. We have different histories. We have different interests. We are well aware that this isn't a struggle between the good guys and the bad guys. All too often, the good guys quickly become the bad guys. Or those that we harshly condemned yesterday magically become the standard-bearers of our alliance for But we share the same planet and ultimately the same destiny. Every day the UN has an increasing reason to exist, and it must inevitably evolve in step with the geopolitical changes unfolding at dizzying speed. Every nation within this organization must play an active role within it, each to the fullest extent of their It's clear that our efforts should focus on ensuring that this is an up-to-date organization properly supported, taking fair decisions that are respected."},{"t":811,"topic":"Border security","text":"Countries borders cannot be subject to human whims. They must be protected and as they represent the boundaries established to preserve identity, distinctive character, and a sense of belonging of their respective populations. We cannot continue to be held hostage to the will of a handful of countries that can be counted on the fingers of one hand. Nor can we yield to the economic expediencies of the time. The aim here is clear. To achieve lasting stability to ensure that the efforts of our citizens and their governments are channeled towards generating prosperity, far removed, of course, from the destruction and suffering caused by war. And we have made a commitment. Let us honor it right now. The history that ultimately prevails will be the history that we write every day through our For all of these reasons, Uruguay will continue to support dialogue, multilateralism, cooperation, international law, and the peaceful settlement of disputes, and above all, for the dignity of every human being."},{"t":891,"topic":"UN operations","text":"Humanity continues to refuse to regard itself as definitively complete, and perhaps that's our greatest hope. The hope that we can still change, that we can still learn, that we can still build, and that we can still choose peace. And this mere fact ultimately reminds us of the clear purity of the idea that together we stand and together we Little is contributed to the purposes of the UN by merely using this rostrum to accuse or attack fire. The fire doesn't need any more Let us better harness this opportunity and let us give peace another chance. Because relations among states just like relations between good people bring happiness. If we refrain from trading blows or elbowing one another aside, thank you very much."},{"t":960,"topic":null,"text":"&gt;&gt; On behalf of the assembly, I wish to thank the president of the Oriental Republic of Uruguay."}],"compare":[{"topic":"International Law & Order","share":0.2236,"mean":0.0595,"rank":7,"others":102},{"topic":"UN & its reform","share":0.1539,"mean":0.205,"rank":116,"others":170},{"topic":"Regional Security","share":0.0892,"mean":0.0042,"rank":3,"others":12},{"topic":"Human Rights","share":0.0839,"mean":0.0082,"rank":5,"others":24},{"topic":"Cuba","share":0.0818,"mean":0.011,"rank":11,"others":23},{"topic":"Artificial Intelligence","share":0.0744,"mean":0.0503,"rank":53,"others":83},{"topic":"Humanitarian Aid","share":0.0736,"mean":0.0015,"rank":2,"others":5},{"topic":"Global Economy","share":0.0713,"mean":0.0143,"rank":18,"others":31}]};
